 let w=unpack(weights);let left=Input{context:c,action:0};let right=Input{context:c,action:1};
 return rl.decide([mass(w,left),mass(w,right)],[pack(gradient(mass,w,left)),pack(gradient(mass,w,right))],[true,true],unit);
}
