fn items<T>(arena:Arena<T>)->List<T> {return arena.items;}
fn spans<T>(arena:Arena<T>)->List<Span> {return arena.spans;}
fn handle<T>(arena:Arena<T>,index:u32)->Option<Handle<T>> {
 let n=length(arena.spans);
