record Scan{engine:Engine,left:u32,right:u32,parent:u32,current:u32,destination:u32,scanning:Bool,done:Bool,}
record Target{id:u64,length:u32,insert:Bool,}
record Walker{engine:Engine,graph:causal.Graph,ends:Map<u64,u32>,identities:intervals.Index,
