 let target=Target{id:s.id,length:take,insert:false};
 return Deleting{..d,engine:Engine{..e,tree:sequence.set_weight<u32>(e.tree,r.slot,0),spans:e.spans.set(r.slot,changed)},targets:d.targets.push(target),remaining:d.remaining-take};
}
fn toggle_step(t:Toggling,insert:Bool,on:Bool)->Toggling{
 let r=identity_location(t.engine,t.id);let r=choose(r.offset==0,r,identity_location(split(r.engine,r.slot,r.offset),t.id));
 let s=r.engine.spans.at_or(r.slot,nil());let take=choose(t.remaining<s.length,t.remaining,s.length);
 if r.slot==0 || take==0 || (!insert && !on && s.deletes==0){let e=r.engine;return Toggling{..t,engine:Engine{..e,error:4},remaining:0};}
