}
record Enabling{flags:List<Bool>,values:Buffer<Bool>,index:u32,run:u32,minimum:u32,}
fn enable_step(e:Enabling)->Enabling{
 let index=e.index-1;let run=choose(e.flags.at_or(index,false),e.run+1,0);
