 assume adjacent(item:u64) requires item<18446744073709551615:
  f(item+1)==f(item);
 f(count)==f(0);
 proof by induction count{
  zero=>normalize;
  succ(previous)=>calc{
   _==f(previous) by assumption adjacent(previous);
    ==_ by ih;
  };
 };
}

