        graph:prefix.graph,flags:prefix.flags,maximum:prefix.maximum,
        minimum:4294967295,index:count-1,valid:prefix.valid,
    },fn(s)=>!s.valid,fn(i,s)=>suffix_step(s));
    return Critical{
        graph:suffix.graph,
        cuts:choose(suffix.valid,suffix.flags.freeze(),[]),
        valid:suffix.valid,
    };
}

