record Toggling{engine:Engine,id:u64,remaining:u32,}
record Walking{walker:Walker,index:u32,}
record Output{engine:Engine,slot:u32,values:Buffer<u32>,}
record Eligibility{ends:Map<u64,Bool>,valid:Bool,}

