 if r.slot==0 || take==0 || (!insert && !on && s.deletes==0){let e=r.engine;return Toggling{..t,engine:Engine{..e,error:4},remaining:0};}
 let e=split(r.engine,r.slot,take);let s=e.spans.at_or(r.slot,nil());
