}
record TargetPass{walker:Walker,index:u32,end:u32,}
fn target_step(p:TargetPass,on:Bool)->TargetPass{
 let target=p.walker.applied.values.at_or(p.index,Target{id:0,length:0,insert:false});let w=p.walker;
