}
fn toggle(e:Engine,target:Target,on:Bool)->Engine{
 let result=repeat_until(target.length,Toggling{engine:e,id:target.id,remaining:target.length},fn(t)=>t.remaining==0 || t.engine.error!=0,fn(i,t)=>toggle_step(t,target.insert,on));
