 let w=prepare(w,c.parents);if w.error!=0 || w.engine.error!=0{return w;}
 let root=w.engine.tree.blocks.at_or(w.engine.tree.root,sequence.empty_block());
 if c.position>root.live || c.remove>root.live-c.position{return Walker{..w,error:4};}
 let d=repeat_until(c.remove,Deleting{engine:w.engine,targets:builder.begin<Target>(w.applied),remaining:c.remove,position:c.position},fn(d)=>d.remaining==0 || d.engine.error!=0,fn(i,d)=>delete_step(d));
 let insertid=c.id+word_widen_u32_to_u64(c.remove);let count=length(c.text);
 let e=choose(count==0,d.engine,inserted(d.engine,insertid,c.position,c.text));
 let targets=choose(count==0,d.targets,builder.push<Target>(d.targets,Target{id:insertid,length:count,insert:true}));
 var ends:Map<u64,u32>=w.ends;var parents:Buffer<u32>=Buffer.empty();
 for p in c.parents{parents=parents.push(ends.get_or(p,0));ends=ends;}
 return Walker{..w,engine:e,graph:causal.append(w.graph,parents.freeze()),ends:ends.set(end-1,slot),applied:builder.finish<Target>(targets),last:end-1};
}
fn output_value(o:Output,index:u32)->Output{let value=o.engine.payload.at_or(index,0);return Output{..o,values:o.values.push(value)};}
fn output_span(o:Output)->Output{
 let s=o.engine.spans.at_or(o.slot,nil());let next=o.engine.tree.nodes.at_or(o.slot,sequence.nil<u32>(0)).next;
 let count=choose(s.deleted,0,s.length);
 let out=repeat_until(count,o,fn(o)=>false,fn(i,o)=>output_value(o,s.payload+i));
 return Output{..out,slot:next};
}
fn walked(changes:List<batches.Change>)->Result<List<u32>,reference.Error>{
 var w:Walker=empty();for c in changes{w=apply(w,c);}
 if w.error!=0 || w.engine.error!=0 || !w.graph.valid || !w.engine.ids.valid{return Err(reference.Error.InvalidOperation);}
 let first=w.engine.tree.first;let bound=w.engine.spans.len();
 let out=repeat_until(bound,Output{engine:w.engine,slot:first,values:Buffer.empty()},fn(o)=>o.slot==0,fn(i,o)=>output_span(o));return Ok(out.values.freeze());
}
fn eligible(changes:List<batches.Change>)->Bool{
 var ends:Map<u64,Bool>=Map.empty();var result:Bool=true;
 for c in changes{
  result=result && batches.valid(c);
  for p in c.parents{result=result && ends.get_or(p,false);ends=ends;}
  ends=ends.set(c.id+batches.width(c)-1,true);
 }
 return result;
}
fn completed(result:Result<List<u32>,reference.Error>,changes:List<batches.Change>)->Result<List<u32>,reference.Error>{
 return match result{Ok(text)=>Ok(text),Err(error)=>batches.materialize(changes),};
}
fn materialize(changes:List<batches.Change>)->Result<List<u32>,reference.Error>{
 if batches.is_linear(changes){return batches.linear(changes);}
 return completed(walked(changes),changes);
}

knowledge/libraries/suffix_cross_measure:
module ink.knowledge.suffix_cross_measure_seek;
import "suffix_measure_sequence.ink" as sequence;

// Select with one additive measure, return the selected item's prefix in
// another measure. Requires a tree maintained by the sequence constructors.
// A missing selection returns node/rank/offset zero. The offset uses selection
// units; rank is the observation before the item, excluding that offset.
record Seeking<T>{tree:sequence.Tree<T>,block:u32,index:u32,position:u32,rank:u32,node:u32,offset:u32,done:Bool,}
fn step<T>(s:Seeking<T>,selection:u32,observation:u32)->Seeking<T>{
 let b=s.tree.blocks.at_or(s.block,sequence.empty_block());
 if s.index>=b.count{return Seeking<T>{..s,done:true};}
 let slot=s.tree.children.at_or(b.start+s.index,0);
 if b.leaf{
  let n=s.tree.nodes.at_or(slot,sequence.nil<T>(s.tree.fallback));
  let weight=sequence.item_measure<T>(n,selection);
  if s.position>=weight{return Seeking<T>{..s,index:s.index+1,position:s.position-weight,rank:s.rank+sequence.item_measure<T>(n,observation)};}
  return Seeking<T>{..s,node:slot,offset:s.position,done:true};
 }
 let child=s.tree.blocks.at_or(slot,sequence.empty_block());
 let weight=sequence.measured(child,selection);
 if s.position>=weight{return Seeking<T>{..s,index:s.index+1,position:s.position-weight,rank:s.rank+sequence.measured(child,observation)};}
 return Seeking<T>{..s,block:slot,index:0};
}
fn seek<T>(t:sequence.Tree<T>,position:u32,selection:u32,observation:u32)->sequence.Position<T>{
 let root=t.root;let count=t.blocks.len();let bound=choose(count>130150524,4294967295,count*33);
 let s=repeat_until(bound,Seeking<T>{tree:t,block:root,index:0,position:position,rank:0,node:0,offset:0,done:false},fn(s)=>s.done,fn(i,s)=>step<T>(s,selection,observation));
 return sequence.Position<T>{tree:s.tree,node:s.node,rank:choose(s.node==0,0,s.rank),offset:choose(s.node==0,0,s.offset)};
}

